class Gradebook:
    def __init__(self) -> None:
        # assignment_name -> {"weight": float, "kind": str}
        self._assignments: dict[str, dict] = {}
        # student_name -> {assignment_name: grade}
        self._grades: dict[str, dict[str, float]] = {}

    def add_assignment(self, name: str, weight: float, kind: str = "homework") -> None:
        """kind is "homework" or "quiz"."""
        self._assignments[name] = {"weight": float(weight), "kind": kind}

    def record(self, student: str, assignment: str, grade: float) -> None:
        grade = float(grade)
        if grade < 2.0 or grade > 5.0:
            raise ValueError(f"Grade {grade} is outside the valid scale of 2.0 to 5.0.")

        if student not in self._grades:
            self._grades[student] = {}
        self._grades[student][assignment] = grade

    def average(self, student: str) -> float:
        if not self._assignments:
            return 0.0

        student_grades = self._grades.get(student, {})

        # Collect quizzes to find the one with the lowest grade (if > 1 quiz)
        quizzes = []
        for name, info in self._assignments.items():
            if info["kind"] == "quiz":
                grade = student_grades.get(name, 2.0)
                quizzes.append((name, grade, info["weight"]))

        dropped_quiz_name = None
        if len(quizzes) > 1:
            # Drop the quiz with the lowest grade.
            # In case of ties, any of the lowest can be dropped.
            dropped_quiz = min(quizzes, key=lambda q: q[1])
            dropped_quiz_name = dropped_quiz[0]

        total_weighted_sum = 0.0
        total_weight = 0.0

        for name, info in self._assignments.items():
            if name == dropped_quiz_name:
                continue

            grade = student_grades.get(name, 2.0)
            weight = info["weight"]

            total_weighted_sum += grade * weight
            total_weight += weight

        if total_weight == 0.0:
            return 0.0

        return total_weighted_sum / total_weight
```

